SELECT id, session_id, event_type, page, event_time, MIN(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_min_duration_sec, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_duration_sec, COUNT(duration_sec) OVER (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_count_duration_sec, SUM(duration_sec) OVER (PARTITION BY event_type ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_duration_sec FROM web_events
